import * as THREE from 'three/webgpu';
import gsap from 'gsap';

export default function createNode(config, ctx) {
  const group = new THREE.Group();
  const state = { activeIndex: 0, timelines: [] };

  const navLabels = ['HOME', 'FEATURES', 'COLLECTION', 'PRICING', 'JOURNAL'];
  const colors = {
    paper: 0xe8ecf2,
    accent: 0xff2a38,
    inactive: 0xa6adba,
  };

  const railWidth = 3.6;
  const railHeight = 0.5;
  const itemSpacing = 0.68;

  // Create rail with brushed-metal PBR
  const railGeo = new THREE.PlaneGeometry(railWidth, railHeight);
  const railMat = new THREE.MeshStandardMaterial({
    color: 0x0f0f14,
    metalness: 0.5,
    roughness: 0.55,
    clearcoat: 0.2,
  });
  const railMesh = new THREE.Mesh(railGeo, railMat);
  railMesh.position.z = 0.15;
  group.add(railMesh);

  // Contact shadow plane
  const shadowGeo = new THREE.PlaneGeometry(railWidth + 0.4, railHeight + 0.2);
  const shadowMat = new THREE.MeshBasicMaterial({
    color: 0x000000,
    transparent: true,
    opacity: 0.35,
  });
  const shadowMesh = new THREE.Mesh(shadowGeo, shadowMat);
  shadowMesh.position.z = 0.08;
  shadowMesh.position.y = -0.06;
  group.add(shadowMesh);

  // Navigation items
  const items = navLabels.map((label, idx) => {
    const itemGroup = new THREE.Group();
    itemGroup.position.x = (idx - 2) * itemSpacing;
    itemGroup.index = idx;

    // Create text mesh using fontAtlas
    let textMesh;
    const isActive = idx === 0;

    if (ctx.fontAtlas && typeof ctx.fontAtlas.createMesh === 'function') {
      textMesh = ctx.fontAtlas.createMesh({
        text: label,
        fontSize: 0.13,
        fontWeight: isActive ? 700 : 400,
        color: isActive ? colors.paper : colors.inactive,
        fontFamily: 'JetBrains Mono',
        letterSpacing: 0.08,
      });
    } else {
      // Fallback: create a simple plane with color
      const textGeo = new THREE.PlaneGeometry(0.4, 0.15);
      const textMaterial = new THREE.MeshBasicMaterial({
        color: isActive ? colors.paper : colors.inactive,
      });
      textMesh = new THREE.Mesh(textGeo, textMaterial);
    }

    textMesh.position.z = 0.16;
    itemGroup.add(textMesh);
    itemGroup.textMesh = textMesh;

    group.add(itemGroup);
    return itemGroup;
  });

  // Underline bar for active state
  const underlineGeo = new THREE.PlaneGeometry(0.28, 0.025);
  const underlineMat = new THREE.MeshBasicMaterial({
    color: colors.accent,
    emissive: colors.accent,
    emissiveIntensity: 1.8,
  });
  const underlineMesh = new THREE.Mesh(underlineGeo, underlineMat);
  underlineMesh.position.set((0 - 2) * itemSpacing, -0.06, 0.16);
  group.add(underlineMesh);

  // Event handlers
  group.userData.handlers = {
    onHover: (idx) => {
      if (state.activeIndex === idx) return;
      const tween = gsap.to(items[idx].textMesh.material, {
        color: colors.paper,
        duration: 0.16,
        ease: 'cubic-bezier(0.25,0.46,0.45,0.94)',
      });
      state.timelines.push(tween);
    },

    onUnhover: (idx) => {
      if (state.activeIndex === idx) return;
      const tween = gsap.to(items[idx].textMesh.material, {
        color: colors.inactive,
        duration: 0.16,
        ease: 'cubic-bezier(0.25,0.46,0.45,0.94)',
      });
      state.timelines.push(tween);
    },

    onPress: (idx) => {
      const t1 = gsap.to(items[idx], {
        scaleX: 0.97,
        scaleY: 0.97,
        duration: 0.12,
        ease: 'cubic-bezier(0.175,0.885,0.32,1.275)',
      });
      const t2 = gsap.to(items[idx].position, {
        z: -0.03,
        duration: 0.12,
        ease: 'cubic-bezier(0.175,0.885,0.32,1.275)',
      });
      state.timelines.push(t1, t2);
    },

    onRelease: (idx) => {
      const t1 = gsap.to(items[idx], {
        scaleX: 1,
        scaleY: 1,
        duration: 0.12,
        ease: 'cubic-bezier(0.175,0.885,0.32,1.275)',
      });
      const t2 = gsap.to(items[idx].position, {
        z: 0,
        duration: 0.12,
        ease: 'cubic-bezier(0.175,0.885,0.32,1.275)',
      });
      state.timelines.push(t1, t2);
    },

    setActive: (idx) => {
      if (state.activeIndex === idx) return;
      const prevIdx = state.activeIndex;
      state.activeIndex = idx;

      // Update text colors
      const t1 = gsap.to(items[prevIdx].textMesh.material, {
        color: colors.inactive,
        duration: 0.2,
      });
      const t2 = gsap.to(items[idx].textMesh.material, {
        color: colors.paper,
        duration: 0.2,
      });

      // Animate underline bar
      const t3 = gsap.to(underlineMesh.position, {
        x: (idx - 2) * itemSpacing,
        duration: 0.26,
        ease: 'cubic-bezier(0.165,0.84,0.44,1)',
        overwrite: false,
      });

      state.timelines.push(t1, t2, t3);
    },
  };

  // Mount animation: rise-in
  const mountTween = gsap.from(group.position, {
    y: 0.4,
    duration: 0.7,
    ease: 'cubic-bezier(0.215,0.61,0.355,1)',
  });
  state.timelines.push(mountTween);

  // Cleanup function
  group.userData.cleanup = () => {
    state.timelines.forEach(tl => tl.kill());
    state.timelines = [];

    gsap.killTweensOf([
      group,
      underlineMesh,
      underlineMesh.position,
      ...items,
      ...items.map(i => i.position),
      ...items.map(i => i.textMesh?.material),
    ]);

    // Dispose geometries and materials
    railGeo.dispose();
    railMat.dispose();
    shadowGeo.dispose();
    shadowMat.dispose();
    underlineGeo.dispose();
    underlineMat.dispose();

    items.forEach(item => {
      item.children.forEach(child => {
        if (child.geometry) child.geometry.dispose();
        if (child.material) child.material.dispose();
      });
    });
  };

  return group;
}
